describe('Phone Number Field Numeric Input Validation', () => {
  beforeEach(() => {
    cy.visit('/contact-form');
  });

  it('should accept only numeric input in phone number field', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/submit-contact').as('submitContact');

    // Locate the phone number input field
    cy.get('[data-testid="phone-number-input"]').should('be.visible');

    // Type a valid numeric phone number
    cy.get('[data-testid="phone-number-input"]').type('1234567890');

    // Verify the field contains only numbers
    cy.get('[data-testid="phone-number-input"]').should('have.value', '1234567890');

    // Attempt to submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call
    cy.wait('@submitContact');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });

  it('should reject non-numeric characters and display error message', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/submit-contact').as('submitContact');

    // Locate the phone number input field
    cy.get('[data-testid="phone-number-input"]').should('be.visible');

    // Attempt to type non-numeric characters
    cy.get('[data-testid="phone-number-input"]').type('123-4-67');

    // Verify the field only contains numeric characters (should strip non-numeric)
    cy.get('[data-testid="phone-number-input"]').should('have.value', '12346');

    // Attempt to submit the form with invalid input
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call
    cy.wait('@submitContact');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Phone number must contain only digits');

    // Verify form was not submitted successfully
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify the phone number field still has the invalid value
    cy.get('[data-testid="phone-number-input"]').should('have.value', '12346');
  });
});
